function lay(cx,cz,rot,probeX,probeZ){
  const t=topAt(probeX,probeZ);
  if(!t||t[0]<0){log("no top "+probeX+","+probeZ);return -1;}
  const r=on('3039',4,t[0],cx-t[2],cz-t[3],rot);
  if(r<0) log("fail "+cx+","+cz);
  return r;
}
const xs=[-4,-2,0,2,4];
for(const x of xs){
  lay(x,-3,180,x-1,-4);
  lay(x,3,0,x-1,3);
  lay(x,-1,180,x-1,-2);
  lay(x,1,0,x-1,1);
}
log("parts="+count());

